CREATE TABLE start_journals(key TEXT PRIMARY KEY,project_id TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id),identity_hash TEXT NOT NULL,draft_json TEXT NOT NULL,draft_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('prepared','committed','acknowledged','abandoned')),run_id TEXT REFERENCES stage_runs(id),CHECK((state IN ('prepared','abandoned') AND run_id IS NULL) OR (state IN ('committed','acknowledged') AND run_id IS NOT NULL)));
CREATE UNIQUE INDEX one_pending_start_per_project ON start_journals(project_id) WHERE state IN ('prepared','committed');
CREATE TRIGGER immutable_start_draft BEFORE UPDATE ON start_journals WHEN NEW.key!=OLD.key OR NEW.project_id!=OLD.project_id OR NEW.task_id!=OLD.task_id OR NEW.identity_hash!=OLD.identity_hash OR NEW.draft_json!=OLD.draft_json OR NEW.draft_hash!=OLD.draft_hash BEGIN SELECT RAISE(ABORT,'immutable start draft'); END;
CREATE TRIGGER start_journal_transition BEFORE UPDATE ON start_journals WHEN NOT ((OLD.state='prepared' AND NEW.state='committed') OR (OLD.state='prepared' AND NEW.state='abandoned') OR (OLD.state='committed' AND NEW.state='acknowledged' AND NEW.run_id=OLD.run_id)) BEGIN SELECT RAISE(ABORT,'invalid start journal transition'); END;
CREATE TRIGGER validate_start_journal_insert BEFORE INSERT ON start_journals WHEN NEW.state!='prepared' OR NOT EXISTS(SELECT 1 FROM tasks t WHERE t.id=NEW.task_id AND t.project_id=NEW.project_id AND t.state='ready') BEGIN SELECT RAISE(ABORT,'invalid start draft task'); END;
CREATE TRIGGER validate_start_journal_receipt BEFORE UPDATE ON start_journals WHEN NEW.run_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM start_requests s JOIN stage_runs r ON r.id=s.run_id WHERE s.key=NEW.key AND s.payload_hash=NEW.identity_hash AND s.run_id=NEW.run_id AND r.task_id=NEW.task_id) BEGIN SELECT RAISE(ABORT,'start journal receipt mismatch'); END;
CREATE TRIGGER reject_sealed_or_changed_start BEFORE INSERT ON start_requests WHEN EXISTS(SELECT 1 FROM start_journals j WHERE j.key=NEW.key AND (j.identity_hash!=NEW.payload_hash OR j.state!='prepared')) BEGIN SELECT RAISE(ABORT,'sealed or changed start'); END;
CREATE TRIGGER commit_start_journal AFTER INSERT ON start_requests WHEN EXISTS(SELECT 1 FROM start_journals j WHERE j.key=NEW.key AND j.state='prepared') BEGIN UPDATE start_journals SET state='committed',run_id=NEW.run_id WHERE key=NEW.key; END;
CREATE TRIGGER preserve_start_journals BEFORE DELETE ON start_journals BEGIN SELECT RAISE(ABORT,'preserve start journal'); END;
PRAGMA user_version=8;
